        "p": "ಯುವಕರ ಪರಿಚಯವಾಗುವ ಮೊದಲೇ ಭಕ್ತಿಸಿದ್ಧಾಂತ ಸರಸ್ವತಿಯವರು, ವಿದ್ಯಾವಂತ ಯುವಕರಾದ ನೀವು ಕೃಷ್ಣನ ಸಂದೇಶವನ್ನು ಜಗತ್ತಿನಾದ್ಯಂತ ಏಕೆ ಪ್ರಚಾರ ಮಾಡುವುದಿಲ್ಲ ಎಂದು ಕೇಳಿದರು. ಪರಾಧೀನ ದೇಶದ ಮಾತನ್ನು ಯಾರೂ ಕೇಳುವುದಿಲ್ಲವಾದ್ದರಿಂದ ಮೊದಲು ಭಾರತ ಸ್ವತಂತ್ರವಾಗಬೇಕು ಎಂದು ಅಭಯರು ಉತ್ತರಿಸಿದರು. ಕೃಷ್ಣನ ಸಂದೇಶವು ರಾಜಕೀಯ ಬದಲಾವಣೆಗಾಗಿ ಕಾಯಲು ಸಾಧ್ಯವಿಲ್ಲ; ಯಾರು ಆಳುತ್ತಾರೆ ಎಂಬುದರ ಮೇಲೆ ಅದು ಅವಲಂಬಿಸಿಲ್ಲ, ಭಗವದ್ಗೀತೆಯ ಬೋಧನೆಗಳು ಕಾಯಲಾಗದಷ್ಟು ಮುಖ್ಯವಾದವು ಎಂದು ಭಕ್ತಿಸಿದ್ಧಾಂತ ಸರಸ್ವತಿಯವರು ಶಾಂತವಾಗಿ ಉತ್ತರಿಸಿದರು."
