        "p": "ಅವರು ಭಗವದ್ಗೀತೆ, ಶ್ರೀಮದ್ಭಾಗವತ ಮತ್ತು ಚೈತನ್ಯ ಚರಿತಾಮೃತವನ್ನು ಸ್ಪಷ್ಟ ಆಧುನಿಕ ಇಂಗ್ಲಿಷ್‌ನಲ್ಲಿ ಅನುವಾದಿಸಿ ವಿವರಿಸಿದರು ಮತ್ತು ಇನ್ನೂ ಅನೇಕ ಗ್ರಂಥಗಳನ್ನು ಬರೆದರು. ಅವು ಈಗ ಎಂಬತ್ತಕ್ಕೂ ಹೆಚ್ಚು ಭಾಷೆಗಳಲ್ಲಿವೆ ಮತ್ತು ವಿದ್ವಾಂಸರ ಮೆಚ್ಚುಗೆ ಪಡೆದಿವೆ. ಅವುಗಳನ್ನು ತಮ್ಮ ಅತ್ಯಂತ ಮುಖ್ಯ ಸೇವೆಯೆಂದು ಪರಿಗಣಿಸಿ, ಅನೇಕ ಬಾರಿ ರಾತ್ರಿಯಿಡೀ ದಣಿವಿಲ್ಲದೆ ಕೆಲಸ ಮಾಡಿದರು."
