    "seoTitle": "ಶ್ರೀಲ ಪ್ರಭುಪಾದ: ಜೀವನ, ಬೋಧನೆಗಳು ಮತ್ತು ಗ್ರಂಥಗಳು",
    "seoDescription": "ಶ್ರೀಲ ಪ್ರಭುಪಾದರು ಇಸ್ಕಾನ್ ಸಂಸ್ಥಾಪಕ-ಆಚಾರ್ಯರು. ಅವರು ಶ್ರೀಕೃಷ್ಣನ ಬೋಧನೆಗಳನ್ನು ಮತ್ತು ಭಕ್ತಿಯೋಗವನ್ನು ಜಗತ್ತಿನಾದ್ಯಂತ ಜನರಿಗೆ ತಲುಪಿಸಿದರು."
