    "biography": [
      {
        "p": "ಭಕ್ತಿವಿನೋದ ಠಾಕೂರರಿಂದ ವೈಷ್ಣವರ ಮುಖ್ಯಸ್ಥರಾದ ವೈಷ್ಣವ ಸಾರ್ವಭೌಮ ಎಂದು ಗೌರವಿಸಲ್ಪಟ್ಟ ಶ್ರೀಲ ಜಗನ್ನಾಥ ದಾಸ ಬಾಬಾಜಿ ಮಹಾರಾಜರು ಸುಮಾರು 1750ರಲ್ಲಿ ಪೂರ್ವ ಬಂಗಾಳದ ಮೈಮನ್‌ಸಿಂಗ್‌ನಲ್ಲಿ ಆವಿರ್ಭವಿಸಿದರು ಮತ್ತು ಬಲದೇವ ವಿದ್ಯಾಭೂಷಣರ ಪರಂಪರೆಯಲ್ಲಿ ಬಾಬಾಜಿ ದೀಕ್ಷೆ ಪಡೆದರು. ಖ್ಯಾತ ಸಿದ್ಧ-ಬಾಬಾ ಆಗಿದ್ದ ಅವರು ತಮ್ಮ ವರ್ಷಗಳನ್ನು ವ್ರಜ ಮತ್ತು ನವದ್ವೀಪಗಳಲ್ಲಿ ಕಳೆದರು ಮತ್ತು ಬಹಳ ದೀರ್ಘಾಯುಷಿಗಳಾಗಿದ್ದರು. ವೃದ್ಧಾಪ್ಯದಲ್ಲಿ ಅವರ ಸೇವಕ ಬಿಹಾರಿ ಅವರನ್ನು ಬುಟ್ಟಿಯಲ್ಲಿ ಹೊತ್ತೊಯ್ಯುತ್ತಿದ್ದರು, ಆದರೂ ಕೀರ್ತನೆಯಲ್ಲಿ ಅವರು ಮೇಲಕ್ಕೆ ಹಾರಿ ನರ್ತಿಸುತ್ತಿದ್ದರು. 1893ರಲ್ಲಿ, ಭಕ್ತಿವಿನೋದ ಠಾಕೂರರು ಪತ್ತೆಹಚ್ಚಿದ್ದ ಸ್ಥಳದಲ್ಲಿ ಅವರು ಬುಟ್ಟಿಯಿಂದ ಹಾರಿ ಭಾವಪರವಶರಾಗಿ ನರ್ತಿಸಿ, ಅದು ಮಹಾಪ್ರಭುಗಳ ಜನ್ಮಸ್ಥಳವೆಂದು ದೃಢಪಡಿಸಿದರು. ಭಗವಂತನ ಪಾರ್ಷದರ ಆವಿರ್ಭಾವ ಮತ್ತು ತಿರೋಭಾವ ದಿನಗಳ ವೈಷ್ಣವ ಪಂಚಾಂಗವನ್ನು ಸಿದ್ಧಪಡಿಸುವಂತೆ ಯುವ ಭಕ್ತಿಸಿದ್ಧಾಂತ ಸರಸ್ವತಿಯವರಿಗೆ ಹೇಳಿದರು. ತಮ್ಮ ಗೋವರ್ಧನ ಶಿಲೆಯನ್ನು ಭಕ್ತಿವಿನೋದ ಠಾಕೂರರಿಗೆ ನೀಡಿದರು. ಗೌರ ಪೂರ್ಣಿಮೆಗೆ ಎರಡು ವಾರ ಮೊದಲು, ಫಾಲ್ಗುಣ ಅಮಾವಾಸ್ಯೆಯಂದು ಅವರು ನಿರ್ಗಮಿಸಿದರು; ಅವರ ಸಮಾಧಿ ನವದ್ವೀಪದ ಕೋಲದ್ವೀಪದಲ್ಲಿ (ಕುಲಿಯಾ) ಇದೆ."
      },
      {
        "p": "ಅವರು ನಿದ್ರೆಯಿಲ್ಲದೆ ದಿನಗಟ್ಟಲೆ ಜಪಿಸುತ್ತಿದ್ದರು, ಚಾತುರ್ಮಾಸ್ಯ ವ್ರತಗಳನ್ನು ಕಟ್ಟುನಿಟ್ಟಾಗಿ ಪಾಲಿಸುತ್ತಿದ್ದರು; ಒಮ್ಮೆ ಬಿಹಾರಿಯೊಂದಿಗೆ ಒಂದು ಮಾತು ಆಡಿದ್ದಕ್ಕಾಗಿ ಮೂರು ತಿಂಗಳ ಪುರಶ್ಚರಣ ವ್ರತವನ್ನು ಮತ್ತೆ ಆರಂಭಿಸಿದರು. ಒಬ್ಬ ಶ್ರೀಮಂತನಿಗೆ ಅದರ ಭಾರ ಹೊರಲಾರೆ ಎಂದು ಹೇಳಿ ಒಂದು ರೂಪಾಯಿಯನ್ನು ಹಿಂದಿರುಗಿಸಿದರು; ಬಾಬಾಜಿ ವೇಷದ ಕಪಟಿಗಳಿಗೆ ಉಣಿಸುವ ಬದಲು ಒಮ್ಮೆ ನವದ್ವೀಪದ ಹಸುಗಳಿಗಾಗಿ ರಸಗುಲ್ಲಾ ಕೊಂಡರು. ಕುಲಿಯಾದಲ್ಲಿ ಮೂವತ್ತೆರಡು ವರ್ಷ ವಾಸಿಸಿ, ತಮ್ಮ ಗಿರಿಧಾರಿಗೆ ಪ್ರತಿದಿನ ಸಾವಿರ ನಮಸ್ಕಾರ ಸಲ್ಲಿಸುತ್ತಿದ್ದರು; ಜಪಕ್ಕೆ ಉತ್ತಮ ಸಮಯ ಬೆಳಿಗ್ಗೆ 3ರಿಂದ 7 ಮತ್ತು ಸೂರ್ಯಾಸ್ತದಿಂದ ರಾತ್ರಿ 11ರವರೆಗೆ ಎನ್ನುತ್ತಿದ್ದರು."
      }
    ],
