    "biography": [
      {
        "p": "ಕೃಷ್ಣಲೀಲೆಯಲ್ಲಿ ಅನಂಗ ಮಂಜರಿ (ಅಥವಾ ಗುಣ ಮಂಜರಿ) ಆದ ಶ್ರೀಲ ಗೋಪಾಲ ಭಟ್ಟ ಗೋಸ್ವಾಮಿಗಳು (1503-1578) ಶ್ರೀರಂಗದ ವೆಂಕಟ ಭಟ್ಟರ ಪುತ್ರರು; 1511ರಲ್ಲಿ ಚಾತುರ್ಮಾಸ್ಯದ ನಾಲ್ಕು ತಿಂಗಳು ಮಹಾಪ್ರಭುಗಳು ಅವರ ಮನೆಯಲ್ಲಿ ತಂಗಿದ್ದರು. ಬಾಲಕ ಗೋಪಾಲರು ಭಗವಂತನ ಸೇವೆ ಮಾಡಿದರು ಮತ್ತು ಕೃಷ್ಣನ ಪರಮತ್ವದ ಕುರಿತ ಅವರ ಬೋಧನೆಗಳಿಂದ ಆಕರ್ಷಿತರಾದರು. ತಮ್ಮ ಚಿಕ್ಕಪ್ಪ ಮತ್ತು ಗುರುಗಳಾದ ಪ್ರಬೋಧಾನಂದ ಸರಸ್ವತಿಯವರಿಂದ ತರಬೇತಿ ಪಡೆದ ಅವರು ತಂದೆತಾಯಿಯರ ನಿಧನದ ನಂತರ ವೃಂದಾವನಕ್ಕೆ ಬಂದರು; ಭಗವಂತನು ತಮ್ಮದೇ ಆಸನ ಮತ್ತು ವಸ್ತ್ರವನ್ನು ಅವರಿಗೆ ಕಳುಹಿಸಿದನು. ಗಂಡಕಿ ನದಿಯಿಂದ ಅವರು ಹನ್ನೆರಡು ಶಾಲಗ್ರಾಮ ಶಿಲೆಗಳನ್ನು ತಂದರು; 1542ರಲ್ಲಿ ನರಸಿಂಹ ಚತುರ್ದಶಿಯಂದು ಅವುಗಳಲ್ಲಿ ಒಂದು ಸುಂದರ ಶ್ರೀ ರಾಧಾರಮಣ ವಿಗ್ರಹವಾಗಿ ಪ್ರಕಟವಾಯಿತು; ಇಂದಿಗೂ ವೃಂದಾವನದಲ್ಲಿ ಅವರನ್ನು ಆರಾಧಿಸಲಾಗುತ್ತದೆ. ಅವರು ಸನಾತನ ಗೋಸ್ವಾಮಿಯವರೊಂದಿಗೆ ಹರಿಭಕ್ತಿ ವಿಲಾಸವನ್ನು ಸಂಕಲಿಸಿದರು, ಸತ್ಕ್ರಿಯಾ ಸಾರ ದೀಪಿಕೆಯನ್ನು ಬರೆದರು ಮತ್ತು ಜೀವ ಗೋಸ್ವಾಮಿಯವರ ಷಟ್ ಸಂದರ್ಭಕ್ಕೆ ಅಡಿಪಾಯ ಹಾಕಿದರು. ಶ್ರೀನಿವಾಸ ಆಚಾರ್ಯರು ಮತ್ತು ಗೋಪೀನಾಥ ಪೂಜಾರಿ ಅವರ ಶಿಷ್ಯರು. ವಿನಯದಿಂದ ಅವರು ಚೈತನ್ಯ ಚರಿತಾಮೃತದಲ್ಲಿ ತಮ್ಮ ಹೆಸರು ಉಲ್ಲೇಖಿಸಬಾರದೆಂದು ಕೇಳಿಕೊಂಡರು. ಅವರ ಸಮಾಧಿ ರಾಧಾರಮಣ ದೇವಾಲಯದಲ್ಲಿದೆ."
      },
      {
        "p": "ವೃಂದಾವನದಲ್ಲಿ ಅವರು ಸಂಚಾರಿ ಭಿಕ್ಷುವಾಗಿ ಬದುಕಿದರು; ರಾತ್ರಿಗಳನ್ನು ಬೇರೆಬೇರೆ ಕುಂಡಗಳಲ್ಲಿ ಕಳೆದು, ಹಗಲನ್ನು ಅಧ್ಯಯನ ಮತ್ತು ಬರವಣಿಗೆಯಲ್ಲಿ ಕಳೆಯುತ್ತಿದ್ದರು. ವರ್ಸಾನ ಮತ್ತು ನಂದಗ್ರಾಮದ ನಡುವಿನ ಸಂಕೇತದಲ್ಲಿ ಅನೇಕ ವರ್ಷ ಭಜನೆ ಮಾಡಿದರು; ಕೊನೆಯ ವರ್ಷಗಳಲ್ಲಿ ರಘುನಾಥ ದಾಸ, ಕೃಷ್ಣದಾಸ ಕವಿರಾಜ ಮತ್ತು ರಘುನಾಥ ಭಟ್ಟರೊಂದಿಗೆ ರಾಧಾಕುಂಡದಲ್ಲಿ ವಾಸಿಸಿದರು. ಗೋಸ್ವಾಮಿಗಳ ಮೂಲ ಶ್ರೀವಿಗ್ರಹಗಳಲ್ಲಿ ಇಂದಿಗೂ ವೃಂದಾವನದಲ್ಲೇ ಇರುವವರು ರಾಧಾರಮಣರು ಮಾತ್ರ; ಗೋಪೀನಾಥ ಪೂಜಾರಿಯವರ ಸಹೋದರ ದಾಮೋದರ ದಾಸರ ವಂಶಸ್ಥರು ಅವರ ಸೇವೆ ಮಾಡುತ್ತಾರೆ."
      }
    ],
