    "title": "ವೃಂದಾವನದ ಷಡ್ ಗೋಸ್ವಾಮಿಗಳಲ್ಲಿ ಒಬ್ಬರು, ಶ್ರೀಮದ್ಭಾಗವತದ ಶ್ರೇಷ್ಠ ವಾಚಕರು",
    "sampradaya": "ಬ್ರಹ್ಮ-ಮಾಧ್ವ-ಗೌಡೀಯ",
