    "summary": "ಗದಾಧರ ಪಂಡಿತರ ಶಿಷ್ಯರು. ವಂಶೀವಟದಲ್ಲಿ ಪ್ರಾಚೀನ ಗೋಪೀನಾಥ ವಿಗ್ರಹವನ್ನು ಮರಳಿ ಪಡೆದು, ವೃಂದಾವನದ ಏಳು ಪ್ರಮುಖ ಗೋಸ್ವಾಮಿ ದೇವಾಲಯಗಳಲ್ಲಿ ಒಂದನ್ನು ಸ್ಥಾಪಿಸಿದರು.",
    "biography": [
      {
        "p": "ಶ್ರೀ ಗದಾಧರ ಪಂಡಿತರ ಶಿಷ್ಯರಾದ ಶ್ರೀಲ ಮಧು ಪಂಡಿತ ಗೋಸ್ವಾಮಿಗಳು ಬಂಗಾಳದ ಖರ್ದಹದ ಬಳಿಯ ಸೈಬೋನಾದವರು; ಗೋಲೋಕದಲ್ಲಿ ಅವರು ಚಂಪಕಲತಾ ಸಖಿಯ ಗುಂಪಿನಲ್ಲಿ ಸೇವೆ ಮಾಡುತ್ತಾರೆ. ಗುರುಗಳ ಆದೇಶದಂತೆ ಅವರು ವೃಂದಾವನಕ್ಕೆ ಬಂದು, ವಜ್ರನಾಭರು ಮೊದಲು ಪ್ರತಿಷ್ಠಾಪಿಸಿದ್ದ ಪ್ರಾಚೀನ ಗೋಪೀನಾಥ ವಿಗ್ರಹಕ್ಕಾಗಿ ಎಲ್ಲೆಡೆ ಹುಡುಕಿದರು. ಸಿಗದಿದ್ದಾಗ ಅವರು ಆಹಾರ ತ್ಯಜಿಸಿ ವಂಶೀವಟದಲ್ಲಿ ಅಳುತ್ತಾ ಕುಳಿತರು. ಮಳೆಗಾಲದ ಪ್ರವಾಹವೊಂದು ಅಲ್ಲಿನ ಹಳೆಯ ಆಲದ ಮರವನ್ನು ಕೊಚ್ಚಿಕೊಂಡು ಹೋದ ನಂತರ, ಅವರ ಸ್ನೇಹಿತ ಪರಮಾನಂದ ಭಟ್ಟಾಚಾರ್ಯರು ನೆಲದಲ್ಲಿ ಅರ್ಧ ಹೂತುಹೋಗಿದ್ದ ವಿಗ್ರಹವನ್ನು ಕಂಡರು; ಮಧು ಪಂಡಿತರು ಅವರನ್ನು ಹೊರತೆಗೆದರು. ರಾಧಾ-ಗೋಪೀನಾಥ ವೃಂದಾವನದ ಏಳು ಪ್ರಮುಖ ಗೋಸ್ವಾಮಿ ದೇವಾಲಯಗಳಲ್ಲಿ ಒಂದಾಯಿತು; ವಿಶಿಷ್ಟವಾಗಿ, ಜಾಹ್ನವಾ ಮಾತೆ ಕಳುಹಿಸಿದ ಅನಂಗ ಮಂಜರಿ ಗೋಪೀನಾಥನ ಎಡಭಾಗದಲ್ಲಿ ನಿಂತಿದ್ದಾಳೆ. ಶ್ರೀನಿವಾಸ, ನರೋತ್ತಮ ಮತ್ತು ಶ್ಯಾಮಾನಂದರು ಗೋಸ್ವಾಮಿಗಳ ಗ್ರಂಥಗಳೊಂದಿಗೆ ಹೊರಟಾಗ ಮಧು ಪಂಡಿತರು ಗೋಪೀನಾಥನ ಹಾರವನ್ನು ಆಶೀರ್ವಾದವಾಗಿ ನೀಡಿದರು. ಅವರ ಸಮಾಧಿ ಗೋಪೀನಾಥ ದೇವಾಲಯದ ಪೂರ್ವ ದ್ವಾರದ ಬಳಿ ಇದೆ."
      },
      {
        "p": "ರಾಜಸ್ಥಾನದ ಶೇಖಾವತ್ ರಾಜಕುಮಾರರಲ್ಲಿ ಒಬ್ಬರಾದ ರಾಜಾ ಸಗನ್‌ಜಿ ಕಟ್ಟಿಸಿದ ಮೂಲ ಗೋಪೀನಾಥ ದೇವಾಲಯ 1589ರಲ್ಲಿ ತೆರೆಯಿತು ಎಂದು ನಂಬಲಾಗಿದೆ; 1670ರಲ್ಲಿ ಔರಂಗಜೇಬನ ಸೈನಿಕರು ಅದನ್ನು ಅಪವಿತ್ರಗೊಳಿಸಿದ ನಂತರ ಅದರ ಪಕ್ಕದಲ್ಲಿ ಹೊಸ ದೇವಾಲಯ ಕಟ್ಟಲಾಯಿತು; ಮೂಲ ವಿಗ್ರಹವನ್ನು ಈಗ ಜೈಪುರದಲ್ಲಿ ಆರಾಧಿಸಲಾಗುತ್ತದೆ. ಅನಂಗ ಮಂಜರಿ ಮತ್ತು ರಾಧಾರಾಣಿಯರ ಇದೇ ವ್ಯವಸ್ಥೆಯನ್ನು ವ್ರಜದ ಎಲ್ಲ ಗೋಪೀನಾಥ ದೇವಾಲಯಗಳಲ್ಲಿ ಅನುಸರಿಸಲಾಗುತ್ತದೆ. ಯಾರ ಕೃಪೆಯಿಂದ ಭಗವಂತನು ಪ್ರಕಟನಾದನೋ ಆ ಮಧು ಪಂಡಿತರನ್ನು ಅದ್ಭುತ ಗುಣಗಳ ನೆಲೆ ಎಂದು ಭಕ್ತಿ-ರತ್ನಾಕರ ಕೀರ್ತಿಸುತ್ತದೆ."
      }
    ],
