    "seoTitle": "ಶ್ರೀ ಶ್ಯಾಮಾನಂದ ಪ್ರಭು: ಜೀವನ ಮತ್ತು ಬೋಧನೆಗಳು",
    "seoDescription": "ಹೃದಯ ಚೈತನ್ಯರ ಶಿಷ್ಯರು, ಜೀವ ಗೋಸ್ವಾಮಿಯವರ ವಿದ್ಯಾರ್ಥಿ. ರಾಧಾರಾಣಿಯ ಕಾಲ್ಗೆಜ್ಜೆ ಮತ್ತು ಶ್ಯಾಮಸುಂದರರನ್ನು ಪಡೆದು, ಒಡಿಶಾದಲ್ಲಿ ಗೌಡೀಯ ವೈಷ್ಣವ ಧರ್ಮ ಹರಡಿದರು."
