    "summary": "ವಿಶ್ವನಾಥ ಚಕ್ರವರ್ತಿಯವರ ಶಿಷ್ಯರು. 1706ರಲ್ಲಿ ಜೈಪುರದ ಗಲ್ತಾದಲ್ಲಿ ಗೋವಿಂದ ಭಾಷ್ಯವನ್ನು ಬರೆದು, ವೇದಾಂತ ಸಂಪ್ರದಾಯಗಳ ನಡುವೆ ಗೌಡೀಯ ಸಂಪ್ರದಾಯದ ಸ್ಥಾನವನ್ನು ಭದ್ರಪಡಿಸಿದರು.",
    "biography": [
      {
        "p": "ಚೈತನ್ಯಲೀಲೆಯಲ್ಲಿ ಗೋಪೀನಾಥ ಆಚಾರ್ಯ ಮತ್ತು ಕೃಷ್ಣಲೀಲೆಯಲ್ಲಿ ರತ್ನಾವಳಿ ಎಂದು ವರ್ಣಿಸಲ್ಪಡುವ ಶ್ರೀಲ ಬಲದೇವ ವಿದ್ಯಾಭೂಷಣರು ಒಡಿಶಾದ ರೆಮುಣಾದ ಬಳಿ ಜನಿಸಿದರು. ಪ್ರತಿಭಾವಂತ ವಿದ್ವಾಂಸರಾದ ಅವರು ಮೊದಲು ಮಾಧ್ವ ಪರಂಪರೆಯಲ್ಲಿ ಸಂನ್ಯಾಸಿಯಾದರು; ನಂತರ ರಸಿಕಾನಂದರ ಶಿಷ್ಯರಾದ ರಾಧಾ-ದಾಮೋದರ ದೇವ ಗೋಸ್ವಾಮಿಯವರು ಅವರಿಗೆ ಮಹಾಪ್ರಭುಗಳ ಬೋಧನೆಗಳನ್ನು ಪರಿಚಯಿಸಿದರು. ಮುಂದೆ ಅವರು ವೃಂದಾವನದಲ್ಲಿ ವಿಶ್ವನಾಥ ಚಕ್ರವರ್ತಿ ಠಾಕೂರರ ಬಳಿ ಅಧ್ಯಯನ ಮಾಡಿದರು. 1706ರಲ್ಲಿ ಜೈಪುರದ ಬಳಿಯ ಗಲ್ತಾದಲ್ಲಿ, ಗೌಡೀಯರಿಗೆ ವೇದಾಂತ ಸೂತ್ರದ ವ್ಯಾಖ್ಯಾನವಿಲ್ಲ ಎಂಬ ಕಾರಣಕ್ಕೆ ಗೋವಿಂದಜಿಯನ್ನು ಆರಾಧಿಸುವ ಅವರ ಹಕ್ಕನ್ನು ರಾಮಾನಂದಿಗಳು ಪ್ರಶ್ನಿಸಿದಾಗ, ಬಲದೇವರು ಶ್ರೀ ಗೋವಿಂದನಿಗೆ ಮೊರೆಯಿಟ್ಟರು. ಕನಸಿನಲ್ಲಿ ಭಗವಂತನು ಒಂದು ವ್ಯಾಖ್ಯಾನವನ್ನು ಹೇಳಿಸುವುದಾಗಿ ವಚನವಿತ್ತನು; ಬಲದೇವರು ಗೋವಿಂದ ಭಾಷ್ಯವನ್ನು ಬರೆದರು; ಅದು ವಿರೋಧಿಗಳನ್ನು ಮೌನಗೊಳಿಸಿ, ಜ್ಞಾನವೇ ಆಭರಣವಾದವರು ಎಂಬ ಅರ್ಥದ ವಿದ್ಯಾಭೂಷಣ ಬಿರುದನ್ನು ಅವರಿಗೆ ತಂದುಕೊಟ್ಟಿತು. ಪ್ರಮೇಯ ರತ್ನಾವಳೀ ಮತ್ತು ಗೀತಾ ಭಾಷ್ಯ ಸೇರಿದಂತೆ ಇಪ್ಪತ್ತಕ್ಕೂ ಹೆಚ್ಚು ಇತರ ಕೃತಿಗಳನ್ನು ಬರೆದರು. ಅವರು ಶ್ರೀ ಜಯ-ವಿಜಯ ಗೋವಿಂದರನ್ನು ಆರಾಧಿಸಿದರು ಮತ್ತು 1768ರಲ್ಲಿ ವೃಂದಾವನದಲ್ಲಿ ನಿರ್ಗಮಿಸಿದರು."
      },
      {
        "p": "ಪರಿವರ್ತನೆಗೆ ಮೊದಲು ಅವರು ವಿಜಯಿ ವಿದ್ವಾಂಸರಾಗಿ ಸಂಚರಿಸಿ ಅನೇಕ ಪುಣ್ಯಕ್ಷೇತ್ರಗಳ ಪಂಡಿತರನ್ನು ಸೋಲಿಸಿದ್ದರು. ಅವರ ವಿಜಯದ ನಂತರ ರಾಮಾನಂದಿಗಳು ದೀಕ್ಷೆ ಕೇಳಿದರು, ಆದರೆ ಶ್ರೀ ಸಂಪ್ರದಾಯದ ಬಗೆಗಿನ ಗೌರವದಿಂದ ಅವರು ನಿರಾಕರಿಸಿದರು. ನಂತರ ಜೈಪುರದ ಮಹಾರಾಜರು ಗೋವಿಂದಜಿಯ ಆರತಿಯನ್ನು ಮೊದಲು ನಡೆಸಬೇಕೆಂದು ಆಜ್ಞಾಪಿಸಿದರು. ಮುಂದೆ ಅವರು ಜೀವ ಗೋಸ್ವಾಮಿಯವರ ಷಟ್ ಸಂದರ್ಭಕ್ಕೆ ವ್ಯಾಖ್ಯಾನ ಆರಂಭಿಸಿದರು. ಗೋವಿಂದ ದಾಸ ಎಂದೂ ಪ್ರಸಿದ್ಧರಾದ ಅವರ ಶಿಷ್ಯರಲ್ಲಿ ಉದ್ಧವ ದಾಸರು ಒಬ್ಬರು; ಅವರ ಪರಂಪರೆ ಜಗನ್ನಾಥ ದಾಸ ಬಾಬಾಜಿಯವರವರೆಗೆ ಸಾಗಿತು. ಗಲ್ತಾದಲ್ಲಿನ ಅವರ ಸಣ್ಣ ದೇವಾಲಯದಲ್ಲಿ ಇಂದಿಗೂ ಸುಮಾರು ನೂರು ಶಾಲಗ್ರಾಮ ಶಿಲೆಗಳಿವೆ."
      }
    ],
